        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel&#x27; — Cyril marks the peplērōtai ho kairos (the time is fulfilled) as the kerygmatic-Markan incipit. The four imperatives compress the entire Christic call: the kairos-fulfilled (incarnational-now), the basileia-engiken (kingdom-near), metanoeite (repent — deep-mind-change), pisteuete (believe — covenantal-trust). Tewahedo evangelization-language preserves the metanoeite-pisteuete pair as the dual-call of every catechetical-summons.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
