        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They were astonished at his doctrine: for he taught them as one that had authority, and not as the scribes&#x27; — Cyril marks the exeplēssonto (astounded-out-of-themselves) and exousia-not-as-scribes pair as Mark&#x27;s earliest Christological-authority signature (paired with Mt 7:28 γ.4.6.B Sermon-conclusion). The Markan-place is the Capernaum synagogue — the FIRST recorded public-teaching moment in Mark. Tewahedo catechetical pedagogy cites Mk 1:22 + Mt 7:28 + Lk 4:32 as the triple-exousia anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
