        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;He healed many that were sick of divers diseases, and cast out many devils; and suffered not the devils to speak, because they knew him&#x27; — Cyril marks the Markan-distinctive &#x27;suffered not the devils to speak&#x27; (ouk ēphien lalein) as the messianic-secret motif. The demonic-Christology is correct (they-knew-him) but premature for human-disciple-instruction; Christ silences the demons until the disciples can confess him from faith (Mk 8:29). Tewahedo Christological-pedagogy preserves the gradual-disclosure principle in catechumenal-formation.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
