        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Son, thy sins be forgiven thee&#x27; — Cyril marks the Markan-order: the paralytic&#x27;s friends&#x27; faith (the four-bearers lowering-through-the-roof, Mk 2:3-4) precipitates Christ&#x27;s-pronouncement before any verbal-request. Christ-sees-the-faith (idōn tēn pistin) and responds with what&#x27;s actually needed first — forgiveness-of-sins. The Pharisaic-objection (only-God-forgives, Mk 2:7) provokes the Son-of-Man-exousia-on-earth demonstration at Mk 2:10. Tewahedo sacramental-confession theology (the Säwasǝw-of-Penitence) cites Mk 2:5 + Mt 9:2 + Lk 5:20 as the triple paralytic-forgiveness anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
