        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;That ye may know that the Son of man hath power on earth to forgive sins, (he saith to the sick of the palsy,) Arise, take up thy bed, and go thy way unto thine house&#x27; — Cyril marks the Markan-version exactly like Matthew&#x27;s (Mt 9:6 γ.4.6.C anchor): the visible miracle authenticates the invisible absolution. The Son-of-Man exousia-on-earth is precisely the divine forgiving-prerogative exercised in the flesh. Tewahedo sacramental-confession theology cites Mk 2:10 + Mt 9:6 + Lk 5:24 as the triple Son-of-Man-authority anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
