        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Arise, and take up thy bed, and go thy way into thine house&#x27; — Cyril marks the three-fold imperative (egeire-aron-hypage: arise-take-up-go) as the resurrection-pattern in miniature. The paralytic&#x27;s previously-stationary state is overcome by Christic-command. The household-going (eis ton oikon sou) is the social-reincorporation that completes the healing. Tewahedo deliverance-ministry tradition cites Mk 2:11 as the healing-and-restoration double-pattern (healing-of-body + restoration-to-community).</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
