        17,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They that are whole have no need of the physician, but they that are sick: I came not to call the righteous, but sinners to repentance&#x27; — Cyril&#x27;s medical-Christology Markan-version. The iatros (physician) image is Cyril&#x27;s deepest soteriological metaphor (cf. Mt 9:12 γ.4.6.C anchor). The Markan ouk-ēlthon-kalesai-dikaious-alla-hamartōlous (I-came-not-to-call-the-righteous-but-sinners) is the missional-priority statement. Tewahedo monastic spiritual-direction reads the abba as iatros-tēs-psychēs (physician-of-the-soul) on the Cyrillian model.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
