        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;If a kingdom be divided against itself, that kingdom cannot stand&#x27; — Cyril marks the basileia-meristheisa-kath-heautēs (a kingdom divided against itself) syllogism as the rebuttal-of-Beelzebub-charge. If Satan-by-Satan cast out Satan, his-kingdom is-self-divided and cannot-stand. The argument is internal-consistency: the Pharisees&#x27; theory undoes itself. Tewahedo anti-Schism ecclesiology cites Mk 3:24-25 alongside 1 Cor 1:10-13 as the unity-against-internal-division anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
