        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;That seeing they may see, and not perceive; and hearing they may hear, and not understand; lest at any time they should be converted, and their sins should be forgiven them&#x27; — Cyril marks Isa 6:9-10 LXX as the parable-rationale-cite. The hina (in-order-that) is purposive but not deterministic: the divine-intention is just-judgment (those-who-refused-the-clear-word receive-the-veiled-word) WHILE preserving-the-possibility-of-conversion (the mēpote, &#x27;lest at any time&#x27;, signals possibility-not-foreclosure). Tewahedo prophetic-judgment hermeneutic + free-will-soteriology balance precisely as Cyril reads here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
