        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The sower soweth the word&#x27; — Cyril marks ho speirōn-ton-logon-speirei (the-sower-sows-the-word) as the parable-key. The seed IS the word (Mark explicit; Matthew implicit). This makes the four-soils a hermeneutic of word-reception, not seed-quality. The Logos sown into hearts is the same seed in every soil; the soil-condition determines the harvest. Tewahedo Word-of-God hermeneutics + monastic-lectio-divina formation are grounded in this Cyrillian seed-as-Logos reading.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
