        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;These are they by the way side, where the word is sown; but when they have heard, Satan cometh immediately, and taketh away the word that was sown in their hearts&#x27; — Cyril marks the Markan-distinctive Satan (Mt 13:19&#x27;s &#x27;wicked one&#x27;; Lk 8:12&#x27;s &#x27;devil&#x27;) as personalized opposition. The euthys-erchetai-ho-Satanas (immediately Satan comes) names the temporal-urgency of the spiritual-opposition. Tewahedo spiritual-warfare theology (the qǝddus-against-evil-spirits tradition) cites Mk 4:15 + Eph 6:11-12 as the post-evangelization vigilance anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
