        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;These are they which are sown on good ground; such as hear the word, and receive it, and bring forth fruit, some thirtyfold, some sixty, and some an hundred&#x27; — Cyril marks the triakonta-hexēkonta-hekaton (30-60-100) progression as the diversified-fruitfulness pattern. The Markan-version preserves the same thirty-sixty-hundred as Matthew (Mt 13:23 γ.4.6.C anchor — though Matthew gives them in descending 100-60-30 order). Tewahedo monastic-lay distinction reads the threefold-fruit as qǝddus / bahǝtawi / mǝʿǝmǝn vocational tiers.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
