        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Is a candle brought to be put under a bushel, or under a bed? and not to be set on a candlestick?&#x27; — Cyril marks the rhetorical-question form (the only-Mark detail vs Matthew&#x27;s declarative) as deliberate-pedagogy: the disciples are MADE to answer the obvious no. The lychnos (lamp) is the kerygma of the kingdom; the modios (bushel) and klinē (bed) are concealment-vessels; the lychnia (lampstand) is the proper-public-position. Tewahedo public-liturgy theology (the qǝddus-sǝbkät proclamation-pattern) anchors here against any esoteric-Christian-temptation.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
