        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;For there is nothing hid, which shall not be manifested; neither was any thing kept secret, but that it should come abroad&#x27; — Cyril marks the Markan-distinctive eis-phaneron-elthē (should come into the open) as the eschatological-disclosure principle. What is now hidden (the kingdom-mystery in parables) will-be-revealed at the Parousia. The lamp-image (Mk 4:21 γ.4.7 seed-anchor) is amplified here. Tewahedo Parousia-eschatology cites Mk 4:22 + Mt 10:26 + Lk 8:17 as the triple eschatological-manifestation prooftext.</p></aside>',
