        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;With what measure ye mete, it shall be measured to you: and unto you that hear shall more be given&#x27; — Cyril marks the Markan-version (only Mark links the Mt-7:2-style-measure-reciprocity to LEARNING; Matthew applies it to judgment). The measure-by-which-we-listen is the measure-by-which-we-receive. The prosthēsetai-hymin (more shall be added to you) names the compounding-return on attentive-discipleship. Tewahedo catechetical-attentiveness tradition cites Mk 4:24 as the growth-by-listening principle.</p></aside>',
