        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;What have I to do with thee, Jesus, thou Son of the most high God? I adjure thee by God, that thou torment me not&#x27; — Cyril marks the Gerasene-demoniac&#x27;s confession (hyiou tou theou tou hypsistou — Son of the Most High God) as the deepest-demonic-Christology in the Synoptics. The exorkizō se ton theon (I-adjure-thee-by-God) is the demon&#x27;s-failed-counter-exorcism — demons-cannot-banish-the-Holy-One. The &#x27;Legion&#x27; identity (Mk 5:9) suggests Roman-occupation imagery; the swine-destruction (Mk 5:13) is the unclean-spirits-into-unclean-animals symbolic-disposition. Tewahedo exorcism-rite cites Mk 5:1-20 as the comprehensive-demoniac-deliverance pattern.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
