        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he asked him, What is thy name? And he answered, saying, My name is Legion: for we are many&#x27; — Cyril marks the Markan-distinctive name-asking + Legion-naming as a deliberate-narrative device. The legiōn (Latin loanword in Greek; ~6,000 soldiers) names the multiplicity of demons inhabiting the man. The hoti-polloi-esmen (for we are many) is the demonic-self-disclosure. Tewahedo deliverance-ministry tradition recognizes the multi-demon-possession category from this Markan precedent.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
