        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Go home to thy friends, and tell them how great things the Lord hath done for thee, and hath had compassion on thee&#x27; — Cyril marks the Markan-distinctive sending-home (not common with post-exorcism narratives elsewhere). The de-formerly-possessed-man becomes the FIRST GENTILE EVANGELIST: he proclaims &#x27;in Decapolis how great things Jesus had done for him&#x27; (Mk 5:20). Tewahedo Aksumite-origin missionary-theology — the Cushite-Gentile-territory evangelized by the formerly-possessed — reads Mk 5:19-20 as proto-missionary-paradigm.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
