        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;My little daughter lieth at the point of death: I pray thee, come and lay thy hands on her, that she may be healed; and she shall live&#x27; — Cyril marks Jairus&#x27;s eschatōs-echei (at-the-last-extremity) as the urgent-faith-petition. The synagōgē-archisynagōgos (synagogue-ruler) is a Jewish-religious-official — yet he comes to Christ across the social-divide between Pharisaic-establishment and Galilean-rabbi. Tewahedo episcopal-petition tradition + compassion-ministry for desperate-cases cite Mk 5:22-24 + Mt 9:18 + Lk 8:41-42 as the urgent-pastoral-care anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
