        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Be not afraid, only believe&#x27; — Cyril marks the Markan-direct address to Jairus (mē phobou monon pisteue) as the central-faith-imperative at the moment of news-of-death. Jairus has just heard &#x27;thy daughter is dead; why troublest thou the Master any further?&#x27; (Mk 5:35); Christ&#x27;s mē-phobou-monon-pisteue is the faith-against-death-itself charge. Tewahedo deathbed-and-funeral pastoral-care tradition cites Mk 5:36 + Heb 11:1 as the faith-beyond-sight anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
