        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;A prophet is not without honour, but in his own country, and among his own kin, and in his own house&#x27; — Cyril marks the Markan-version (slightly fuller than Mt 13:57) as the kenotic-hiddenness in incarnate-particularity. The familiar-Nazareth neighbors see the carpenter&#x27;s-son they grew up with; faith-eyes are required to see the divine-Logos beneath. The thrice-qualified rejection-locus (patris + syngeneis + oikia — country, kin, house) intensifies the offense. Tewahedo Christological-preaching cites Mk 6:1-6 + Jn 1:11 (came-unto-his-own) as the twofold-rejection-witness.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
