        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They cast out many devils, and anointed with oil many that were sick, and healed them&#x27; — Cyril marks the Markan-distinctive oil-anointing in the apostolic-mission (ēleiphon elaiō, anointed with oil). This is the only Synoptic passage where the Twelve are described doing this; James 5:14 picks up the same practice (presbyters-anoint-with-oil-in-the-Lord&#x27;s-name). Tewahedo sacrament-of-the-sick (qǝbʿät-zayit, anointing-of-oil) cites Mk 6:13 + Jas 5:14-15 as the dual-foundation of the rite.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
