        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;It is not lawful for thee to have thy brother&#x27;s wife&#x27; — Cyril marks John-the-Baptist&#x27;s prophetic-rebuke to Herod Antipas (for marrying Herodias, his half-brother Philip&#x27;s wife) as the proper-exercise of prophetic-confrontation against ruler-illegality. The ouk exestin (it-is-not-lawful) echoes Lev 18:16 + 20:21 brother&#x27;s-wife prohibition. John pays for the rebuke with his life. Tewahedo prophet-veneration tradition + ascetic-witness against ruler-vice (notably the bahǝtawi tradition&#x27;s confrontation of kings) cite Mk 6:18 as the prophetic-courage anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
