        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Herod feared John, knowing that he was a just man and an holy, and observed him; and when he heard him, he did many things, and heard him gladly&#x27; — Cyril marks the Markan-distinctive Herod&#x27;s-ambivalence (Matthew omits this nuance). Even the vicious-ruler could recognize-the-prophetic-truth and feel-its-pull (audebat / ēkouen-hēdeōs — gladly-listening). Yet Herodias&#x27;s pressure (Mk 6:19) eventually overcame the king&#x27;s better-instinct. The tragedy is that hearing-gladly-but-not-acting is not enough; Mk 4:17 stony-ground reception. Tewahedo conversion-discipline warns against half-hearted-hearing per Mk 6:20.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
