        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Come ye yourselves apart into a desert place, and rest a while&#x27; — Cyril marks the Markan-distinctive deute hymeis-autoi (you-yourselves) + erēmon-topon (desert-place) + anapausasthe-oligon (rest-a-little) as Christ&#x27;s-pastoral-care for his exhausted-apostles. The disciples have just returned from their first-mission (Mk 6:7-13); the Master prescribes withdrawal-rest. Tewahedo monastic-anchorite tradition (the bahǝtawi-retreat rhythm + the Mahǝbär-feast / weekday-fast rhythm) cites Mk 6:31 as the missionary-rest-charter alongside Ex 33:14 + Heb 4:9-10.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
