        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Jesus, when he came out, saw much people, and was moved with compassion toward them, because they were as sheep not having a shepherd: and he began to teach them many things&#x27; — Cyril marks the Markan-version (parallels Mt 9:36 γ.4.6.C anchor) but with an instructive-emphasis NOT in Matthew: Christ&#x27;s-compassion leads to TEACHING (ērxato didaskein), not just to healing. The shepherd-flock-without-shepherd Ezek 34 imagery operates Christologically — Christ-IS-the-Good-Shepherd (Mk 6:34 + Jn 10:11). Tewahedo episcopal-formation reads Mk 6:34 + Ezek 34 as the teaching-AND-shepherding pastoral dual-charge.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
