        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;He commanded them to make all sit down by companies upon the green grass&#x27; — Cyril marks the Markan-distinctive &#x27;green grass&#x27; (chortō chlōrō) and &#x27;by companies&#x27; (symposia symposia — Hebraic doubling for distribution) as ordered-eucharistic-meal imagery. Mark also gives precise group-sizes Mk 6:40 (in fifties and hundreds, prasiai prasiai). The deliberate-arrangement is liturgical-ordered-table, not random-crowd. The chlōrō-chortō echoes Ps 23:2 LXX &#x27;green pastures&#x27;. Tewahedo Qǝddāse eucharistic-table-arrangement (Aksumite tradition: ordered-communion-by-ranks) traces Cyrillian-Markan precedent here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
