        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;He saw them toiling in rowing; for the wind was contrary unto them: and about the fourth watch of the night he cometh unto them, walking upon the sea, and would have passed by them&#x27; — Cyril marks the Markan-distinctive &#x27;would have passed by them&#x27; (ēthelen parelthein autous) as the theophanic-passing-by motif echoing Ex 33:22 + 1 Kgs 19:11 (the Lord &#x27;passing by&#x27; Moses + Elijah). Christ&#x27;s walking-on-sea is divine-prerogative (Ps 77:19 LXX 76:20) + theophanic-pass-by (Ex 33:22 LXX). The tetartē phylakē (fourth watch, 3-6 AM) names the deepest-night moment of disciples&#x27; distress. Tewahedo theophany-hermeneutics cites Mk 6:48 as Christological-OT-theophany-fulfillment.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
