        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;It is I; be not afraid&#x27; — Cyril marks the egō-eimi-mē-phobeisthe as the Christological-divine-name claim (parallels Mt 14:27 γ.4.6.D anchor). The egō-eimi echoes the Septuagint&#x27;s rendering of Ex 3:14 — the incarnate Word identifies with the I-AM. The Markan-version preserves the SAME formula as the Johannine egō-eimi declarations (Jn 6:20 + Jn 8:24, 58 + Jn 18:5-8). Tewahedo Christological-Tǝmqät hymnody pairs Mk 6:50 + Mt 14:27 + Jn 6:20 as the triple I-AM-on-the-water prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
