        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Whithersoever he entered, into villages, or cities, or country, they laid the sick in the streets, and besought him that they might touch if it were but the border of his garment: and as many as touched him were made whole&#x27; — Cyril marks the Markan-collective-healing-by-hem-touch as the universal-version of the hemorrhaging-woman&#x27;s individual-touch (Mk 5:28 γ.4.7.B anchor). The kraspedon-touching faith-paradigm scales from one woman to many crowds. The hosoi-an-hēptonto-autou (as-many-as-touched-him) construction signals comprehensive-power-of-the-Christ-touch. Tewahedo healing-pilgrimage tradition + icon-touch dynamics cite Mk 6:56 as scriptural-warrant.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
