        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Well hath Esaias prophesied of you hypocrites, as it is written, This people honoureth me with their lips, but their heart is far from me&#x27; — Cyril marks the Markan citation of Isa 29:13 LXX as the diagnostic-prooftext for Pharisaic-hypocrisy. The hypokritai (hypocrites — actors-with-masks) honors-with-lips-but-not-heart is the lip-service-without-heart-service indictment. Tewahedo anti-hypocrisy catechesis cites Mk 7:6-7 + Isa 29:13 + Mt 15:7-8 as the triple lip-service warning.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
