        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;In vain do they worship me, teaching for doctrines the commandments of men&#x27; — Cyril marks matēn-sebontai-me (in-vain-they-worship-me) as the deepest possible indictment: their worship is fruitless because its-content is human-tradition not divine-commandment. The didaskontes-didaskalias-entalmata-anthrōpōn (teaching-doctrines-the-commandments-of-men) inverts the proper-relation (divine-doctrines-shape-human-conduct). Tewahedo doctrinal-discipline (Mäshafä-Qǝddǝse hermeneutic) distinguishes Apostolic-tradition (paradosis) from human-innovation precisely on the Cyrillian-Markan principle.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
