        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Full well ye reject the commandment of God, that ye may keep your own tradition&#x27; — Cyril marks the deliberate-irony in kalōs-atheteite (well do ye set aside) — the kalōs is ironic, naming the proficiency-of-rejecting. The contrast: paradosin-hymōn (your-tradition) vs entolēn-tou-theou (commandment-of-God) — human-tradition AGAINST divine-commandment, not human-tradition AS divine-commandment. Tewahedo Apostolic-tradition vs human-innovation discernment depends on this Cyrillian-Markan distinction.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
