        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;But ye say, If a man shall say to his father or mother, It is Corban, that is to say, a gift, by whatsoever thou mightest be profited by me; he shall be free&#x27; — Cyril marks the Markan-preserved Aramaic &#x27;Corban&#x27; (qorbān, gift-to-God dedication) with the Greek gloss &#x27;dōron&#x27; (gift). The Pharisaic-loophole: vowing-resources-as-Corban frees them from filial-obligation to support parents (violating Ex 20:12). Christ exposes the loophole as commandment-subversion. Tewahedo filial-piety tradition cites Mk 7:9-13 as the anti-loophole + Honor-Father-and-Mother absolute-priority.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
