        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;There is nothing from without a man, that entering into him can defile him: but the things which come out of him, those are they that defile the man&#x27; — Cyril treats the Markan-version alongside Mt 15:11 (γ.4.6.C anchor) — the deeper hermeneutical principle that interior-uncleanness exceeds ritual-uncleanness. Mark 7:19&#x27;s parenthetical &#x27;making all foods clean&#x27; (kathirizōn panta ta brōmata) is the Markan-editorial-clarification that doesn&#x27;t abolish Lev 11 categorically but names the interior-priority hermeneutic. Tewahedo dietary-discipline retains the OT Lev 11 + Acts 15 framework while reading Mk 7:15 as the interior-priority anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
