        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;For from within, out of the heart of men, proceed evil thoughts, adulteries, fornications, murders, thefts&#x27; — Cyril marks the Markan-fuller list of interior-defilement-sources (13 items in Mk 7:21-22; Matthew gives 7 at Mt 15:19). The kardia (heart) is the source; the body merely externalizes what&#x27;s-inside. The vice-catalogue technique (paralleling Rom 1:29-31, Gal 5:19-21, etc.) sets the moral-diagnostic lens. Tewahedo penitential-catechesis (the Säwasǝw of Penitence) draws on Mk 7:21-22 + Gal 5:19-21 as the inward-moral-examination corpus.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
