        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;From thence he arose, and went into the borders of Tyre and Sidon, and entered into an house, and would have no man know it: and he could not be hid&#x27; — Cyril marks the Markan-distinctive &#x27;would have no man know it&#x27; (oudena ēthelen gnōnai) as the Christic-mission-quietness motif. Even crossing into Gentile-territory (Tyre + Sidon — Phoenician), Christ-intends-incognito; the Syrophoenician-woman&#x27;s faith breaks the silence (Mk 7:25-30). Tewahedo missionary-quiet-witness tradition (the unobtrusive-presence pattern of the Nine-Saints and contemporary Tewahedo-missions) draws Christic-warrant here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
