        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Looking up to heaven, he sighed, and saith unto him, Ephphatha, that is, Be opened&#x27; — Cyril marks the Markan-preserved-Aramaic Ephphatha (ethphatah, be-opened) as the climactic-creative-word (echoing Gen 1&#x27;s let-there-be). Christ&#x27;s anablepsas (looking-up) + estenaxen (sighed-deeply) shows the Christic-emotional-involvement in healing. Tewahedo baptismal-rite explicitly preserves the Ephphatha gesture: the priest touches the candidate&#x27;s ears + mouth + nostrils saying &#x27;Ephphatha — Be opened — for the proclamation of the Gospel and the praise of God&#x27; (Coptic-Tewahedo continuity from the Mark-Aramaic source).</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
