        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;I have compassion on the multitude, because they have now been with me three days, and have nothing to eat&#x27; — Cyril marks the Markan-version (parallels Mt 15:32 γ.4.6.C anchor) of the Feeding-of-4000. The hēmerai-treis (three days) is theological-loaded — the Christic-Passion-resurrection chronology (Mk 8:31). Crowds-with-the-Master-three-days-without-bread receive miraculous-bread; the typology anticipates eucharistic-bread-after-three-days-of-Passion. Tewahedo Holy-Week + Fasika eucharistic-cycle reads Mk 8:2 + Mk 8:31 + Mk 14:22-24 as linked-typological-chain.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
