        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And the Pharisees came forth, and began to question with him, seeking of him a sign from heaven, tempting him&#x27; — Cyril marks peirazontes-auton (tempting-him) as the satanic-language echo (Mk 1:13 wilderness-temptation; Mk 12:15 Caesar-coin test). The Pharisaic sēmeion-apo-tou-ouranou (sign-from-heaven) demand is category-error: signs-from-heaven are God&#x27;s-prerogative, given-when-and-how-God-chooses, not demand-extracted. Tewahedo wonder-discernment tradition (sober skepticism of sign-seeking) draws Mk 8:11-13 + Mt 12:38-39 as anti-sign-demand prooftexts.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
