        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;He sighed deeply in his spirit, and saith, Why doth this generation seek after a sign? verily I say unto you, There shall no sign be given unto this generation&#x27; — Cyril marks the Markan-distinctive anastenaxas-tō-pneumati (sighed-deeply-in-his-spirit) as Christ&#x27;s-emotional-grief at unbelief. The anti-sign declaration is unconditional in Mark (Matthew adds &#x27;except the sign of Jonas&#x27; Mt 12:39 + 16:4). Christ-refuses-to-perform-on-demand; the only-sign-coming is the Resurrection-Cross. Tewahedo Christological-Passion-anticipation reads Mk 8:12 alongside Mt 12:39-40 + Jn 2:18-21 (temple-destroyed-raised-in-three-days).</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
