        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Take heed, beware of the leaven of the Pharisees, and of the leaven of Herod&#x27; — Cyril marks the Markan-distinctive &#x27;leaven of Herod&#x27; (Mt 16:6 has &#x27;leaven of the Pharisees and Sadducees&#x27;; Lk 12:1 has just &#x27;leaven of Pharisees, hypocrisy&#x27;). The Markan-Herodian-corruption joins Pharisaic-legalism as twin-defilement-doctrines. Pharisaic-leaven is religious-self-righteousness; Herodian-leaven is political-collaboration-with-tyranny. Tewahedo dual-warning catechesis (against religious-hypocrisy AND political-collaboration-with-power) is grounded in this Cyrillian-Markan dual-leaven reading.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
