        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Why reason ye, because ye have no bread? perceive ye not yet, neither understand? have ye your heart yet hardened?&#x27; — Cyril marks Christ&#x27;s-rebuke pattern (oupō-noeite-oude-syniete — not-yet-perceiving-not-yet-understanding) as the disciple-slowness diagnosis. The pepōrōmenēn-tēn-kardian (hardened-heart) is shocking applied to disciples — the same vocabulary used of Pharisees (Mk 3:5 γ.4.7 seed). Disciples + Pharisees can both share-the-heart-hardening; conversion is ongoing-not-completed. Tewahedo catechetical-realism reads Mk 8:17-21 as honest disciple-formation pedagogy.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
