        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;But whom say ye that I am? And Peter answereth and saith unto him, Thou art the Christ&#x27; — Cyril marks the Markan-compactness (sy ei ho Christos — three words, Mk 8:29; vs Matthew&#x27;s longer &#x27;thou art the Christ, the Son of the living God&#x27;, Mt 16:16) as characteristic of Mark&#x27;s terse-style. The hymeis (emphatic-you, the disciples) contrasts with the earlier &#x27;who-do-men-say-I-am&#x27;. Discipleship-knowledge is FIRST-person, not borrowed-opinion. Tewahedo catechetical-confession (the credo-recitation in Qǝddāse) is the embodied-actualization of every disciple&#x27;s-own Petrine-confession.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
