        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he began to teach them, that the Son of man must suffer many things, and be rejected of the elders, and of the chief priests, and of the scribes, and be killed, and after three days rise again&#x27; — Cyril marks the Markan-first-Passion-prediction as the kerygmatic-turning-point. The dei (it-is-necessary) names divine-soteriological-necessity, not fated-tragedy. The threefold-rejection-source (elders + chief-priests + scribes) names the entire-religious-establishment as conspiring-against-Messiah. The meta treis hēmeras (after-three-days) is the Resurrection-promise paired with every Passion-prediction. Tewahedo Holy-Week lectionary cites Mk 8:31 + Mt 16:21 + Lk 9:22 as the triple Passion-prediction-with-Resurrection-clause.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
