        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Get thee behind me, Satan: for thou savourest not the things that be of God, but the things that be of men&#x27; — Cyril marks Christ&#x27;s-rebuke-to-Peter immediately-after Peter&#x27;s-confession (Mk 8:29 γ.4.7 seed). The hypage-opisō-mou-satana (get-behind-me-Satan) is the strongest Christological rebuke addressed to any disciple in the Gospels. Peter&#x27;s confession-of-Christ (8:29) and rejection-of-Cross (8:32 Peter-rebukes-Jesus-for-predicting-Passion) cannot both stand — the Christ-confessed is-the-Christ-Crucified. Tewahedo Christological-discipleship rules cite Mk 8:33 as the no-Christ-without-Cross anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
