        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel&#x27;s, the same shall save it&#x27; — Cyril marks the Markan-distinctive &#x27;for my sake AND THE GOSPEL&#x27;S&#x27; (heneken emou kai tou euangeliou — Matthew omits the gospel-clause at Mt 16:25). The Markan-addition explicitly grounds the life-losing in evangelical-service. The chiastic save-lose / lose-save kenotic-paradox summarizes discipleship. Tewahedo martyrology + missionary-vocation theology cite Mk 8:35 as the dual-charter (martyric-willing-loss + missionary-gospel-service).</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
