        36,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;For what shall it profit a man, if he shall gain the whole world, and lose his own soul?&#x27; — Cyril marks ti-gar-ōphelei-anthrōpon (for-what-shall-it-profit-a-man) as the universal-moral-summit question. The kerdēsai-ton-kosmon-holon (to-gain-the-whole-world) is the maximal-temporal-profit; zēmiōthē-tēn-psychēn-autou (suffer-loss-of-one&#x27;s-soul) is the maximal-eternal-loss. The asymmetry is decisive: no temporal-profit compensates for soul-loss. Tewahedo wealth-ethics + monastic-renunciation theology cite Mk 8:36 + Lk 9:25 + Mt 16:26 as the triple soul-value-supremacy anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
