        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of man be ashamed, when he cometh in the glory of his Father with the holy angels&#x27; — Cyril marks the Markan-distinctive &#x27;and of my words&#x27; (kai tous emous logous) as the deepest-Logology claim: shame-at-Christ&#x27;s-words IS shame-at-Christ-himself, because the Logos and his-words are ontologically-inseparable. The Parousia-judgment (Christ ashamed-of-them) is the eschatological-mirror. Tewahedo Logos-Christology + Parousia-eschatology read Mk 8:38 as a particularly tight Christological-eschatological summary.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
