    (
        9,
        4,
        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;There appeared unto them Elias with Moses: and they were talking with Jesus&#x27; — Cyril marks the Markan-ordering &#x27;Elias with Moses&#x27; (Matthew + Luke reverse: Moses-and-Elijah). The Markan-ordering may foreground Elijah&#x27;s prominence in second-temple eschatology (Mal 4:5-6, expected-before-Day-of-Lord). Both are present with Christ; Law (Moses) and Prophets (Elijah) testify together. The syllaloûntes-tō-Iēsou (talking-with-Jesus) preserves the conversational-dignity of the OT-witnesses before the incarnate-Word. Tewahedo iconography of the Transfiguration depicts Moses + Elijah flanking Christ.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
    ),
