        5,
        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Master, it is good for us to be here: and let us make three tabernacles; one for thee, and one for Moses, and one for Elias&#x27; — Cyril marks Peter&#x27;s-impulsive-suggestion as the well-meaning-but-misguided desire to-stay-on-the-mountain. The kalon-estin-hēmas-hōde-einai (good-it-is-for-us-here-to-be) is right (the Tabor-vision IS good); the three-skēnas (three-tents — perhaps tabernacles-of-meeting Ex 33:7 OR Feast-of-Tabernacles eschatological-typology) misreads-the-economy. Christ-must-descend-to-Cross before any eschatological-tabernacle is built. Tewahedo eschatological-anticipation discipline cites Peter&#x27;s-error as cautionary precedent.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
