        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And there was a cloud that overshadowed them: and a voice came out of the cloud, saying, This is my beloved Son: hear him&#x27; — Cyril marks the Markan-shortest-form of the Father&#x27;s-voice at the Transfiguration (Matthew adds &#x27;in whom I am well pleased&#x27;; Mark gives just &#x27;this is my beloved Son: hear him&#x27;). The akouete autou (hear-him) is the imperative completing the Tabor-revelation: not just see-the-glory but obey-the-Word. The nephelē episkiazousa (overshadowing-cloud) echoes Ex 40:34-35 Sinai-cloud and Lk 1:35 Marian-overshadowing. Tewahedo Buhe feast iconography depicts the cloud-and-voice prominently per the Markan-form&#x27;s hear-him imperative.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
