        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he said unto them, This kind can come forth by nothing, but by prayer and fasting&#x27; — Cyril marks the Markan-distinctive prayer-AND-fasting prescription for difficult-exorcisms (some textual witnesses preserve only &#x27;prayer&#x27;; the Byzantine majority + Cramer&#x27;s catena tradition preserves &#x27;and fasting&#x27; as Cyril knew it). The to-genos-touto (this-kind, the recalcitrant-demonic-strain) requires-spiritual-disciplines-the-mere-exorcistic-command-lacks. Tewahedo deep-deliverance tradition + Mahǝbär-fast cycles cite Mk 9:29 as the prayer-fasting deliverance-charter.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
