        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The Son of man is delivered into the hands of men, and they shall kill him; and after that he is killed, he shall rise the third day&#x27; — Cyril marks the Markan-second-Passion-prediction (after Mk 8:31 first + Mk 10:33-34 third). The paradidotai (is-being-handed-over — present-tense already-in-process) names the in-progress-betrayal. The &#x27;killed-and-after-three-days-rise&#x27; formula is constant across all three predictions. Tewahedo Holy-Week lectionary reads the three-Passion-predictions (Mk 8:31 + 9:31 + 10:33-34) as the kerygmatic-triple-witness to the deliberate-Christic-path.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
