        35,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;If any man desire to be first, the same shall be last of all, and servant of all&#x27; — Cyril marks the prōtos / eschatos paradox as kingdom-inversion summarized. The diakonos pantōn (servant-of-all) is not optional-humility but constitutive-discipleship: to-serve IS to-be-great-in-the-kingdom. The Markan-context (disciples-disputing-greatness, Mk 9:33-34) sharpens the rebuke. Tewahedo episcopal-formation tradition reads Mk 9:35 + Mk 10:43-45 as the bishop-as-servant double-anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
