        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Whosoever shall receive one of such children in my name, receiveth me: and whosoever shall receive me, receiveth not me, but him that sent me&#x27; — Cyril marks the kinship-chain (receive-child = receive-Christ = receive-Father). The Christic-identification-with-the-least-significant inverts the disciples&#x27;-prior-greatness-dispute (Mk 9:33-34). To-receive-a-child-in-Christ&#x27;s-name is to receive the entire Trinity-through-the-Son-into-the-Father. Tewahedo child-welcoming tradition + Mahǝbär-feast hospitality cite Mk 9:37 as the least-of-these reception anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
