        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Whosoever shall offend one of these little ones that believe in me, it is better for him that a millstone were hanged about his neck, and he were cast into the sea&#x27; — Cyril marks the skandalisē (offend, cause-to-stumble) as the gravest sin against tōn-mikrōn-toutōn-tōn-pisteuontōn (these-little-ones-believing). The hyperbolic-millstone language signals incomparable-seriousness — better-drowning than scandal-causing. Tewahedo pastoral-care + child-protection ethics cite Mk 9:42 as the absolute-prohibition against catechumen-or-disciple harm.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
