        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Salt is good: but if the salt have lost his saltness, wherewith will ye season it? Have salt in yourselves, and have peace one with another&#x27; — Cyril marks the Markan-distinctive echete-en-heautois-halá (have-salt-in-yourselves) + eirēneuete-en-allēlois (be-at-peace-with-one-another) pair as the discipleship-charter. Salt-of-discipleship preserves and seasons (Mk 9:49 every-sacrifice-salted echoes Lev 2:13 covenant-of-salt). Disciples must internalize-the-Christic-quality (salt-in-yourselves) and live-it-out-relationally (peace-with-one-another). Tewahedo monastic-rule + lay-Mahǝbär ethics anchor here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
