        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;From the beginning of the creation God made them male and female&#x27; — Cyril marks the Markan apo-archēs-ktiseōs (from-beginning-of-creation) as the original-design-principle trumping Mosaic-permission-of-divorce (Mk 10:4-5). The Gen 1:27 (arsen-kai-thēly, male-and-female) citation grounds the marital-permanence in protological-ontology, not legal-concession. Tewahedo marital-theology preserves the original-design priority (Gen 1:27 + Gen 2:24 + Mk 10:6-9) over the Mosaic-concession (Deut 24:1) per Cyrillian-precedent.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
