        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Suffer the little children to come unto me, and forbid them not: for of such is the kingdom of God&#x27; — Cyril marks the Markan-double-imperative aphete-ta-paidia-erchesthai (suffer-the-children-to-come) + mē-kōlyete-auta (forbid-them-not) as doubled-Christic-correction of disciple-blocking. The tōn-toioutōn-estin-hē-basileia (of-such-is-the-kingdom) is ontologically-significant — paidic-receptivity is the kingdom-shape. Tewahedo infant-baptism tradition (the early-baptism pattern preserved in Coptic-Tewahedo against Donatist-and-later anti-paedobaptist objections) cites Mk 10:14 as primary warrant.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
