        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Verily I say unto you, Whosoever shall not receive the kingdom of God as a little child, he shall not enter therein&#x27; — Cyril marks hōs-paidion (as-a-little-child) NOT as biological-age but as paidic-receptive-dependency. The dexētai (receive) is passive-grace-receiving, not active-merit-earning. Children model-the-kingdom-economy: dependency, trust, openness, lack-of-self-righteousness. Tewahedo monastic-humility-formation tradition reads Mk 10:15 as the rule-of-the-novice (begin-again-as-paidic-receiver).</p></aside>',
