        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Why callest thou me good? there is none good but one, that is, God&#x27; — Cyril treats this most-difficult-saying carefully. Christ is NOT denying his own goodness or divinity; he is testing the rich-young-ruler&#x27;s understanding of what-he-just-called-Christ. The young-man called Christ &#x27;good Teacher&#x27; as human-flattery without grasping the implication. Christ replies: if I am truly good, then the agathos-is-God-only logic requires recognizing-me-as-God. This is a hidden-Christological-claim, not divinity-denial. Tewahedo Christological-pedagogy reads Mk 10:18 + Lk 18:19 + Mt 19:17 as the deepest-divinity-disclosure under apparent-humility.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
