        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Then Jesus beholding him loved him, and said unto him, One thing thou lackest: go thy way, sell whatsoever thou hast, and give to the poor, and thou shalt have treasure in heaven: and come, take up the cross, and follow me&#x27; — Cyril marks the Markan-distinctive emblepsas-auto-ēgapēsen-auton (beholding-him-loved-him) — the only Gospel-passage where Christ-is-said-to-love-an-individual. The Christic-love is precisely what elicits the costly-call. The hen-soi-hysterei (one-thing-you-lack) is the counsel-of-perfection (cf. Mt 19:21 γ.4.6.D anchor). Tewahedo monastic-vocation theology (the Mäshafä-Mǝnǝkwǝsnna) reads Mk 10:21 as the love-prompting-of-the-calling.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
