        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;It is easier for a camel to go through the eye of a needle, than for a rich man to enter into the kingdom of God&#x27; — Cyril reads kamēlon (camel — NOT kamilon ship-rope per dubious-textual-alternatives) as deliberate-hyperbole. The largest Palestinian animal through the smallest Palestinian aperture: impossibility-by-natural-means, possibility-only-by-grace (Mk 10:27 &#x27;all things are possible with God&#x27;). Tewahedo wealth-ethics cites Mk 10:17-27 alongside Mt 19:16-26 + Lk 18:18-27 as the triple-rich-young-man corpus.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
