        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;With men it is impossible, but not with God: for with God all things are possible&#x27; — Cyril marks Christ&#x27;s-disciples&#x27;-question (who-then-can-be-saved? Mk 10:26) as the kerygmatic-pivot. Human-salvation IS impossible-to-mere-human-effort (con-firming-the-camel-needle of Mk 10:25 γ.4.7 seed). But panta-dynata-para-tō-theō (all-things-possible-beside-God) is the grace-principle. Tewahedo soteriology of grace + divine-monergism-in-conversion reads Mk 10:27 + Mt 19:26 + Lk 18:27 as the triple grace-makes-impossible-possible anchor.</p></aside>',
