        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;But he shall receive an hundredfold now in this time, houses, and brethren, and sisters, and mothers, and children, and lands, with persecutions; and in the world to come eternal life&#x27; — Cyril marks the Markan-distinctive &#x27;with persecutions&#x27; (meta diōgmōn — Matthew and Luke omit this clause) as the honest-realism about disciple-experience. The hundredfold-compensation is genuine but always-with-persecutions-attached. Tewahedo monastic-and-martyric tradition reads Mk 10:30 as the honest-promise + costly-realism balance.</p></aside>',
