        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Ye know not what ye ask: can ye drink of the cup that I drink of? and be baptized with the baptism that I am baptized with?&#x27; — Cyril marks the Markan-distinctive cup-and-baptism pair (Matthew omits the baptism-clause at Mt 20:22 in best texts). The potērion (cup) is the Passion-cup (cf. Mk 14:36); the baptisma (baptism) is the Cross-as-baptism-of-suffering (echoes Lk 12:50 &#x27;I have a baptism to be baptized with&#x27;). Both metaphors converge on Christ&#x27;s-Passion-as-the-disciple&#x27;s-participation. Tewahedo Christological-discipleship reads Mk 10:38-39 as cup-and-baptism dual-participation anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
