        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Ye know that they which are accounted to rule over the Gentiles exercise lordship over them; and their great ones exercise authority upon them&#x27; — Cyril marks the hoi-dokountes-archein (those-supposing-to-rule) as carefully-chosen — Gentile-rulers SUPPOSE to rule but only-Christ-truly-rules. The katakyrieousin-autōn (lord-it-over-them) is the worldly-domination-pattern Christ explicitly rejects for his disciples. Tewahedo episcopal-formation + Mahǝbär-leadership ethics cite Mk 10:42-45 as the anti-domination service-leadership charter (climaxing at Mk 10:45 ransom-for-many γ.4.7 seed).</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
