        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;What wilt thou that I should do unto thee? The blind man said unto him, Lord, that I might receive my sight&#x27; — Cyril marks Christ&#x27;s question (ti soi theleis poiēsō?, what-do-you-will-me-to-do-for-you?) as the deliberate-elicitation-of-explicit-petition. The blind man Bartimaeus must NAME his need; anonymous-faith is not enough at the threshold-of-healing. The Rabboni-vocative (Rabbouni — Mark preserves the Aramaic) + anablepsō (let-me-see-again) signals previously-seeing now-lost — sight-restoration, not original-sight. Tewahedo prayer-formation tradition (precise-petition over vague-yearning) cites Mk 10:51 as exemplar.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
