        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Blessed be the kingdom of our father David, that cometh in the name of the Lord: Hosanna in the highest&#x27; — Cyril marks the Markan-distinctive &#x27;kingdom of our father David that cometh&#x27; (Matthew has the simpler &#x27;Son of David&#x27; Mt 21:9; Mark explicitly names the Davidic-kingdom). The Davidic-messianic anticipation (2 Sam 7:12-13 + Ps 89 covenant) reaches its fulfillment in Christ&#x27;s-entry. Tewahedo Solomonic-Davidic theology (the Kǝbrä Nägäśt&#x27;s Davidic-dynasty claim) reads Mk 11:10 + the Hosanna-Sunday liturgy as a deliberate connection between Israel&#x27;s-Davidic-kingdom and Tewahedo&#x27;s-Solomonic-line.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
