        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They come to Jerusalem: and Jesus went into the temple, and began to cast out them that sold and bought in the temple, and overthrew the tables of the moneychangers, and the seats of them that sold doves&#x27; — Cyril marks the Markan-version of the temple-cleansing (parallels Mt 21:12 γ.4.6.D anchor). The Markan-detail &#x27;seats of them that sold doves&#x27; (kathedras tōn pōlountōn tas peristeras) is specific: doves were the offering-of-the-poor (Lev 12:8); commercial-exploitation of the poor&#x27;s-offering is what Christ overturns. Tewahedo poor-and-marginalized advocacy theology cites Mk 11:15-17 + Isa 56:7 + Jer 7:11 as the temple-as-prayer-not-marketplace anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
