        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;In the morning, as they passed by, they saw the fig tree dried up from the roots&#x27; — Cyril marks the ek-rhizōn (from-the-roots) as the comprehensive-withering signature. Mark&#x27;s-temporal-framing (the fig-cursing on day-1, the withered-fig discovered on day-2) creates the sandwich-structure (Markan-distinctive literary technique) around the temple-cleansing: fig-cursing → temple-judgment → withered-fig. The two-events INTERPRET each other. Tewahedo Holy-Week lectionary preserves the Markan-narrative-order on Holy-Monday.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
