        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Whosoever shall say unto this mountain, Be thou removed, and be thou cast into the sea; and shall not doubt in his heart, but shall believe that those things which he saith shall come to pass; he shall have whatsoever he saith&#x27; — Cyril marks the metabēthi-eis-tēn-thalassan (be-removed-into-the-sea) as the deliberate-hyperbole for the apparently-impossible. The mē-diakrithē (not-doubting) is the dual-mindedness ban (paralleling James 1:6-8). Faith-power requires unmixed-conviction. Tewahedo deep-prayer + healing-ministry tradition reads Mk 11:23-24 + Mt 17:20 + 21:21-22 as the faith-mountain-into-sea triple-anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
