        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses&#x27; — Cyril marks the stēkete-proseuchomenoi-aphiete (standing-praying-forgive) as the prayer-condition. The Markan-version makes forgiveness a prerequisite-of-prayer-being-heard, paralleling the Lord&#x27;s-Prayer&#x27;s conditional-forgiveness petition (Mt 6:12 γ.4.6.B anchor). Cyril reads this NOT as God-needing-our-permission-to-forgive but as our-stance-of-mercy being the channel through which we receive-mercy. Tewahedo sacramental-confession + pre-Eucharistic Pax (reconcile-before-altar) explicitly cite Mk 11:25.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
