        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;By what authority doest thou these things? and who gave thee this authority to do these things?&#x27; — Cyril marks the priests-scribes-elders deputation as the FORMAL Sanhedrin-investigation of Christ&#x27;s-temple-cleansing. The exousia (authority) question is appropriately-religious (priests asking by-what-authority is their job) but inappropriately-blind-to-evidence (Christ&#x27;s-miracles + his-teaching already attest his-authority). Tewahedo anti-blindness-to-evidence catechesis cites Mk 11:27-33 + Jn 5:36-47 + Mt 11:4-5 as the Christic-authority-attestation corpus.</p></aside>',
