        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;A certain man planted a vineyard, and set an hedge about it, and digged a place for the winefat, and built a tower, and let it out to husbandmen, and went into a far country&#x27; — Cyril marks the vineyard-tenants parable as a Christological-covenantal allegory drawing on Isa 5:1-7 (Israel-as-vineyard). The vineyard = Israel; the husbandmen = Israel&#x27;s religious leaders; the servants = prophets; the beloved-son = Christ. The progressive-rejection sequence (servants beaten + killed; son ultimately killed Mk 12:8) summarizes salvation-history. Tewahedo prophetic-rejection theology + martyrdom-of-the-prophets reads Mk 12:1-9 as Cyrillian summary.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
