        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Have ye not read this scripture; The stone which the builders rejected is become the head of the corner: This was the Lord&#x27;s doing, and it is marvellous in our eyes?&#x27; — Cyril cites Ps 118:22-23 (LXX 117:22-23) at the close of the wicked-tenants-parable as the Christological-cornerstone fulfillment (paired with Mt 21:42 γ.4.6.D anchor). The lithon hon apedokimasan (stone-they-rejected) is the Crucifixion; eis kephalēn-gōnias (into head-of-corner) is the Resurrection. Tewahedo Mäzgəbä-Hāymanot doctrine cites Mk 12:10 + Mt 21:42 + Ps 118:22 + Acts 4:11 + 1 Pet 2:6-7 as the five-fold cornerstone-prooftext.</p></aside>',
