        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Render to Caesar the things that are Caesar&#x27;s, and to God the things that are God&#x27;s&#x27; — Cyril marks the Markan-version of the dual-loyalty answer (parallels Mt 22:21 γ.4.6.D anchor). The Markan-version uniquely includes &#x27;they marvelled at him&#x27; (ethaumazon ep&#x27; autō) signaling the Pharisees + Herodians expected to trap-Christ; the answer escapes-the-trap-with-deeper-truth. The denarius bearing Caesar&#x27;s-image belongs-to-Caesar; the human-soul bearing God&#x27;s-image belongs-to-God. Tewahedo political-theology + Solomonic-monarchy tradition operates within this twofold-jurisdiction principle.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
