        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;When they shall rise from the dead, they neither marry, nor are given in marriage; but are as the angels which are in heaven&#x27; — Cyril marks the Sadducees-resurrection-trap rebuttal. Sadducees deny resurrection AND angels (Acts 23:8); Christ affirms BOTH at once. The marital-state of the resurrection-body is NOT continued-earthly-marriage; the resurrection-transformation transcends-and-transfigures-marriage rather than abolishing-it. Tewahedo marital-theology + monastic-eschatology read Mk 12:25 as the marriage-fulfilled-not-annulled in resurrection.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
