        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The first of all the commandments is, Hear, O Israel; The Lord our God is one Lord&#x27; — Cyril marks the Markan-preservation of the Deut 6:4 Shema (the Hebrew Shema in Greek transliteration: akoue Israēl Kyrios ho theos hēmōn Kyrios eis estin). This is the Markan-distinctive — Matthew jumps straight to the love-command (Mt 22:37) without quoting the Shema-incipit. Cyril&#x27;s Trinitarian-monotheism reads Kyrios-heis (Lord-one) as the unity-of-the-Triune-God (Father + Son + Spirit are ONE God, not three gods). Tewahedo Trinitarian-confession + anti-Arian + anti-Sabellian theology grounds in Mk 12:29 + Deut 6:4 + Jn 10:30 + Jn 17:22 as the unity-in-Trinity prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
