        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And the second is like, namely this, Thou shalt love thy neighbour as thyself. There is none other commandment greater than these&#x27; — Cyril marks the Markan-distinctive-conclusion &#x27;there is none other commandment greater than these&#x27; (Matthew expresses similarly Mt 22:40 but in different phrasing). The Lev 19:18 love-neighbor command is paired-equal with the Shema-love-God command — not subordinated but complementary. Cyril&#x27;s anti-anti-nomian reading: Christ doesn&#x27;t abolish-the-Law-of-Moses but compresses-it-to-its-essence. Tewahedo ethical-formation (the Säwasǝw catechetical tradition) cites Mk 12:31 + Lev 19:18 + Mt 22:37-40 + Rom 13:9 as the love-fulfills-the-Law quadruple-anchor.</p></aside>',
