        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;When Jesus saw that he answered discreetly, he said unto him, Thou art not far from the kingdom of God&#x27; — Cyril marks the Markan-distinctive Christic-affirmation of the inquiring-scribe (only Mark records this; Matthew + Luke parallels are sharper). The ou makran (not far) is genuine-affirmation: the scribe&#x27;s thoughtful-response shows kingdom-proximity. Cyril notes that kingdom-of-God is not absolute-distance but degrees-of-approach. Tewahedo catechumenal-progression (the gradual-Mystagogy from outer-court to inner-sanctuary) reads Mk 12:34 as the encouragement-of-the-seeking-soul.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
