        36,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;David himself said by the Holy Ghost, The LORD said to my Lord, Sit thou on my right hand, till I make thine enemies thy footstool&#x27; — Cyril marks the Markan-distinctive &#x27;by the Holy Ghost&#x27; (en tō pneumati tō hagiō) emphasis: David is acknowledged as Spirit-inspired prophetic-author of Ps 110:1. The Davidic-messianic logic: David CALLS the Messiah &#x27;my Lord&#x27;; therefore the Messiah is greater-than-David, not merely David&#x27;s-natural-descendant. Christ&#x27;s question (whose-son-is-the-Messiah, Mk 12:35) exposes Davidic-natural-descent as insufficient — the Messiah must be both Son-of-David AND Son-of-God. Tewahedo Christological-and-Davidic-theology (the Kǝbrä Nägäśt&#x27;s Solomonic-line through-Christ) cites Mk 12:35-37 + Ps 110:1 + Mt 22:41-46 as the Davidic-divinity Christological summary.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
