        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Which devour widows&#x27; houses, and for a pretence make long prayers: these shall receive greater damnation&#x27; — Cyril marks the harshest-of-the-warnings about religious-leaders: the katesthontes-tas-oikias-tōn-chērōn (devour-widows&#x27;-houses) + prophasei makra proseuchomenoi (under-pretext-making-long-prayers). The double-vice (financial-exploitation of widows + ostentatious-piety-as-cover) is hypocrisy-at-its-worst. The perissoteron krima (greater condemnation) is graded-judgment principle. Tewahedo episcopal-discipline + protection-of-the-widow tradition cite Mk 12:40 + Ex 22:22 + Jer 22:3 + Jas 1:27 as the widow-protection corpus.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
