        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Verily I say unto you, That this poor widow hath cast more in, than all they which have cast into the treasury&#x27; — Cyril marks the Markan-precise-evaluation (paralleling Lk 21:1-4). The Christic-arithmetic inverts the temple-treasurer&#x27;s-arithmetic: two-mites &gt; many-rich-coins, because measurement-of-gift follows proportion-of-substance-given, not absolute-coin-value. The next verse (12:44) makes the principle explicit: she gave from her bios (life-substance) not from perisseuontos (abundance). Tewahedo kenotic-stewardship + Mahǝbär-giving tradition cite Mk 12:41-44 + Lk 21:1-4 as the widow-mite exemplar.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
