        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;There shall not be left one stone upon another, that shall not be thrown down&#x27; — Cyril marks the Markan-temple-prophecy (parallel Mt 24:2 + Lk 21:6) as the historical-eschatological double-fulfillment. Historically: AD 70 destruction by Titus (Josephus War). Eschatologically: foreshadows the Parousia-judgment on all human-pretensions to permanence. The lithos ep&#x27; lithon (stone upon stone) negative is comprehensive-destruction. Tewahedo prophetic-historical theology reads Mk 13:2 + Lk 19:43-44 + Mt 24:2 alongside AD 70 historical events as the divine-judgment-on-Pharisaic-temple Christic-prophecy-fulfillment.</p></aside>',
