        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Take heed lest any man deceive you&#x27; — Cyril marks blepete-mē-tis-hymas-planēsē (watch-lest-anyone-deceive-you) as the Olivet-discourse&#x27;s primary-instruction. The deception-warning appears at strategic intervals (13:5, 13:9, 13:23, 13:33). The planos (deceiver) is the eschatological-false-prophet category. Tewahedo doctrinal-discernment + anti-heretic catechesis (Manichaean + Arian + later docetic-incursion against Aksumite Christianity) cites Mk 13:5-6 + 13:21-22 + 1 Jn 4:1-3 as the false-prophet-discernment corpus.</p></aside>',
