        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They shall deliver you up to councils; and in the synagogues ye shall be beaten: and ye shall be brought before rulers and kings for my sake, for a testimony against them&#x27; — Cyril marks the persecution-warning (paradōsousin-hymas, they-will-deliver-you-up — same verb as Christ&#x27;s-betrayal). The synedria (councils) + synagōgas (synagogues) + hēgemonas-kai-basileis (rulers-and-kings) traces the persecution&#x27;s full-jurisdictional-scope (Sanhedrin-Jewish; synagogue-local; Roman-imperial). Tewahedo Sämā&#x27;ǝtāt martyrology preserves the comprehensive-persecution expectation alongside Acts-narrative parallels.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
