        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Now the brother shall betray the brother to death, and the father the son; and children shall rise up against their parents, and shall cause them to be put to death&#x27; — Cyril marks the Markan-fierceness of family-fracture under persecution. The four-relational-axes (brother-brother + father-son + child-parent + child-parent-to-death) name the comprehensive-disruption. Mic 7:6 background: &#x27;the son dishonoreth the father&#x27;. Tewahedo persecution-pastoral-care tradition reads Mk 13:12-13 alongside Mic 7:6 + Mt 10:21 as the family-fractured-by-persecution warning.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
