        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;When ye shall see the abomination of desolation, spoken of by Daniel the prophet, standing where it ought not, (let him that readeth understand,) then let them that be in Judaea flee to the mountains&#x27; — Cyril marks the bdelygma-tēs-erēmōseōs (abomination of desolation) as the Dan 9:27 + 11:31 + 12:11 fulfillment. Historically: read as Titus-army&#x27;s-standards-in-temple OR Caligula-statue-attempted (AD 40 abandoned). Eschatologically: prefigures Antichrist-pretension to divine-honors. The parenthetical &#x27;let him that readeth understand&#x27; (parenthēsei tou anaginōskontos) is a deliberate-reader-alert. Tewahedo apocalyptic-discernment cites Mk 13:14 + Mt 24:15 + Dan 9:27 as the dual-fulfillment anchor.</p></aside>',
