        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Then shall they see the Son of man coming in the clouds with great power and glory&#x27; — Cyril marks the Markan-Parousia-vision with Dan 7:13 (&#x27;one like a Son of Man coming with the clouds&#x27;) as the textual-root. The dynamis-pollē-kai-doxa (great-power-and-glory) is the eschatological-revelation of what was incarnate-hidden during the earthly-ministry. Tewahedo Parousia-eschatology (the Mäshafä-Bǝrhän&#x27;s apocalyptic-section) + Andǝmta commentary on Daniel cite Mk 13:26 + Dan 7:13-14 + Rev 1:7 as the triple Parousia-anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
