        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Heaven and earth shall pass away: but my words shall not pass away&#x27; — Cyril&#x27;s Christological-Logology summit (parallel Mt 24:35 γ.4.6.D anchor). The hoi-logoi-mou (my-words) cannot perish because the speaker IS the eternal Logos. Tewahedo Scripture-doctrine cites Mk 13:31 + Mt 24:35 + Lk 21:33 + Mt 5:18 + Isa 40:8 + 1 Pet 1:25 as the comprehensive Word-eternity prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
