        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;But of that day and that hour knoweth no man, no, not the angels which are in heaven, neither the Son, but the Father&#x27; — Cyril treats this most-difficult-verse carefully. The &#x27;neither the Son&#x27; (oude ho hyios) is read by Cyril per the communicatio-idiomatum: in his incarnate-human-nature the Son-as-man does not know-as-human; in his divine-nature he knows-as-divine-Word. The Tewahedo Miaphysite Christology preserves the Cyrillian-balance: the one Person-of-the-Word experiences knowledge-in-flesh authentically without his divine-omniscience being compromised. Anti-Arian and anti-Agnoetic readings both fail against Cyril&#x27;s careful incarnational-communicatio.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
