        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And what I say unto you I say unto all, Watch&#x27; — Cyril marks the Markan-distinctive universal-extension of the watchfulness imperative. The pasin-legō-grēgoreite (to-all-I-say-watch) broadens beyond the immediate disciple-audience to the entire Church-future. The grēgoreite (be-awake) is the eschatological-vigilance-stance par excellence. Tewahedo Mahǝlet-vigil + monastic-Mahǝbär all-night-prayer tradition cite Mk 13:37 as the universal-vigilance Christic-mandate.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
