    (
        14,
        3,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;A woman having an alabaster box of ointment of spikenard very precious; and she brake the box, and poured it on his head&#x27; — Cyril marks the Markan-distinctive &#x27;broke the box&#x27; (syntripsasa ton alabastron) as the comprehensive-gift signature. The woman doesn&#x27;t pour-from-the-jar; she breaks-the-jar-entirely. The myron-nardou-pistikēs-polytīmou (very-precious genuine-nard) names the costliness — Mk 14:5 specifies 300-denarii value (one-year&#x27;s-wages). The Markan-version anoints the HEAD (messianic-royal anointing); the Johannine-version anoints the FEET (Jn 12:3 — different woman or same in different gesture). Tewahedo Marian-and-women-saints hagiography preserves both Markan-royal + Johannine-humble anointing dimensions.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
    ),
