        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Judas Iscariot, one of the twelve, went unto the chief priests, to betray him unto them&#x27; — Cyril marks the tragic-precision &#x27;one of the twelve&#x27; (heis tōn dōdeka). Judas&#x27;s betrayal is from-within-the-apostolic-circle, not external-conspiracy. The paradō auton (deliver-him-up) is the same verb later applied to Christ being-handed-over and to disciples being-handed-over in persecution. Tewahedo Holy-Wednesday liturgy (Sǝlot-Räbu`a or Wednesday-of-Holy-Week) commemorates Judas&#x27;s-betrayal with fasting + lamentation.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
