        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And as they did eat, Jesus took bread, and blessed, and brake it, and gave to them, and said, Take, eat: this is my body&#x27; — Cyril&#x27;s Eucharistic-realism locus in Mark. The estin (is) is real-identification, not symbolization (cf. Mt 26:26, Lk 22:19, 1 Cor 11:24). The four-action sequence (took-blessed-brake-gave) is the Anaphora-institution-prototype. Tewahedo Qǝddāse-of-the-Apostles cites Mk 14:22-24 + Mt 26:26-28 + Lk 22:19-20 + 1 Cor 11:23-25 as the four-fold institution-witness recited at every Anaphora&#x27;s words-of-institution.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
