        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;This is my blood of the new testament, which is shed for many&#x27; — Cyril&#x27;s Eucharistic-blood institution locus in Mark (parallel Mt 26:28 γ.4.6.D anchor). The Markan-form is slightly more concise than Matthew&#x27;s; both preserve the to-haima-mou-tēs-diathēkēs (my-blood-of-the-covenant) Ex 24:8 covenantal-ratification echo. The peri-pollōn (for-many) is the Septuagint Isa 53:11-12 echo. Tewahedo Anaphora-of-the-Apostles cites Mk 14:22-24 + Mt 26:26-28 + Lk 22:19-20 + 1 Cor 11:23-25 as the four-fold institution-witness verbatim at the institution-rite.</p></aside>',
