        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Verily I say unto you, I will drink no more of the fruit of the vine, until that day that I drink it new in the kingdom of God&#x27; — Cyril marks the Markan-distinctive eschatological-vow (parallels Mt 26:29). The ou-mē-pio (I will absolutely not drink) + kainon (new — qualitatively-new-creation drink) anticipates the eschatological-banquet. The Last-Supper looks forward to the Marriage-Supper-of-the-Lamb (Rev 19:9). Tewahedo eschatological-banquet theology + Anaphora&#x27;s-pointing-forward-to-the-Parousia cite Mk 14:25 + Lk 22:18 + Mt 26:29 + Rev 19:9 as the eschatological-cup-anchor.</p></aside>',
