        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;All ye shall be offended because of me this night: for it is written, I will smite the shepherd, and the sheep shall be scattered&#x27; — Cyril marks Christ&#x27;s-citation of Zech 13:7 as the divinely-foreseen disciple-scattering. The skandalisthēsesthe (you-will-all-be-scandalized) is the disciple-failure-prediction. Yet the Zech 13:7-9 oracle CONTINUES (the smitten-shepherd becomes-the-vindicated-shepherd; the scattered-sheep are-refined-and-restored). Christ&#x27;s-citation invokes the WHOLE oracle, not just the scattering-clause. Tewahedo restoration-after-failure theology + Petrine-restoration tradition read Mk 14:27 + Zech 13:7-9 + Jn 21:15-17 as the smitten-shepherd-restored-flock anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
