        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Verily I say unto thee, That this day, even in this night, before the cock crow twice, thou shalt deny me thrice&#x27; — Cyril marks the Markan-distinctive &#x27;before the cock crow TWICE&#x27; (Matthew + Luke + John have simply &#x27;before cock crow&#x27;). The Markan-precise-detail (likely from Peter&#x27;s-own-recollection — the early-church tradition holds Mark as Peter&#x27;s-translator) preserves the two-stage cock-crow that Peter would have remembered. Tewahedo Holy-Friday liturgy + Petrine-restoration narrative tradition preserve the dual-cock-crow detail.</p></aside>',
