        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;There followed him a certain young man, having a linen cloth cast about his naked body; and the young men laid hold on him: And he left the linen cloth, and fled from them naked&#x27; — Cyril marks the Markan-distinctive young-man-fled-naked detail (found ONLY in Mark) as the evangelist&#x27;s-signature. Tradition (Coptic + Tewahedo + Greek-patristic) holds that this neaniskos (young man) is John Mark himself — the future Coptic-founder + Tewahedo-lineage-anchor — preserving an eyewitness-memory of his own youthful-Gethsemane-flight in the third-person. The shame-of-fleeing-naked is balanced by the later-courage-to-write-the-Gospel. Tewahedo Coptic-John-Mark-veneration tradition cites Mk 14:51-52 as the evangelist&#x27;s-personal-presence proof.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
