        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The high priest asked him, and said unto him, Art thou the Christ, the Son of the Blessed?&#x27; — Cyril marks the Markan-distinctive &#x27;the Son of the Blessed&#x27; (tou-Eulogētou) as Caiaphas&#x27;s deliberate-circumlocution to avoid uttering the Tetragrammaton. Eulogētos (Blessed One) is a standard rabbinic-substitute-name-for-God. The question is the definitive-Sanhedrin-test (parallel Mt 26:63 γ.4.6.D Cyril-noted anchor). Christ&#x27;s-affirmative-reply (Mk 14:62 below) commits him to crucifixion-as-blasphemer-by-Sanhedrin-judgment.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
