        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And Jesus said, I am: and ye shall see the Son of man sitting on the right hand of power, and coming in the clouds of heaven&#x27; — Cyril marks Christ&#x27;s-affirmative egō-eimi (I am — the divine-I-AM Ex 3:14) PLUS the Ps 110:1 right-hand-of-power-citation PLUS the Dan 7:13 coming-in-clouds-citation. THREE Christological claims in one declaration: (1) divine-name self-identification; (2) royal-priestly-enthronement at Father&#x27;s-right; (3) eschatological-Parousia-coming. The Markan-version is the boldest-Synoptic affirmation (Matthew has &#x27;thou hast said&#x27; Mt 26:64). Tewahedo Christological-Trinitarian doctrine cites Mk 14:62 + Ps 110:1 + Dan 7:13 as the triple-identity prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
