        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Pilate asked him, Art thou the King of the Jews? And he answering said unto him, Thou sayest it&#x27; — Cyril marks su-legeis (thou-sayest-it) as Christ&#x27;s enigmatic-affirmative — neither denial nor unqualified-yes, but YES-with-redefinition. Pilate&#x27;s-Roman-meaning of &#x27;king of the Jews&#x27; is political-rebellion; Christ&#x27;s-meaning is messianic-Davidic-kingship of an-other-kingdom (Jn 18:36 &#x27;my kingdom is not of this world&#x27;). Tewahedo Christological-royal theology + the Kǝbrä Nägäśt&#x27;s kingship-not-of-this-world tradition cite Mk 15:2 + Jn 18:36 + Mt 27:11 as the Christic-other-kingdom anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
