        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The chief priests moved the people, that he should rather release Barabbas unto them&#x27; — Cyril marks the chief-priests&#x27; manipulation of crowd-opinion (aneseisan-ton-ochlon, stirred-up-the-crowd). The Barabbas-substitution irony is profound: Bar-abba (son-of-the-father) is released; the true-Son-of-the-Father is condemned. A genuine-insurrectionist-murderer (Mk 15:7) is preferred over the innocent-Lord. Tewahedo Holy-Friday-theology + atonement-substitution reads Mk 15:6-15 as the explicit-substitution-typology (the innocent-One taking the guilty-one&#x27;s-place).</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
