        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They clothed him with purple, and platted a crown of thorns, and put it about his head&#x27; — Cyril marks the mockery-coronation as theologically-true-despite-being-intended-ironically. The porphyran (purple — royal-color) + stephanon-akanthinon (crown-of-thorns) are mocking-versions of royal-investiture; but Christ IS the true King, and the thorns recall Gen 3:18&#x27;s-curse on the ground — Christ wears the curse so we don&#x27;t. Tewahedo Christological-paradox theology + the Mahǝlet-Mǝrhǝbāne hymnody cite Mk 15:17 + Gen 3:18 + Heb 2:9 as the thorn-crown-bearing-the-curse anchor.</p></aside>',
