        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross&#x27; — Cyril marks the Markan-distinctive precise-detail &#x27;father of Alexander and Rufus&#x27; (these sons must have been known to Mark&#x27;s-Roman-audience; Rom 16:13 mentions a &#x27;Rufus&#x27;). Simon-of-Cyrene is from North-Africa (Cyrene = Libya); his compulsion-to-bear-Cross may have led to his and his sons&#x27; later conversion. The Tewahedo Aksumite-African-connection reads Mk 15:21 as the FIRST African-figure to bear-the-Cross — a typological-anchor for Tewahedo&#x27;s-Cushite-Cross-bearing mission. The Coptic-tradition specifically honors Simon-of-Cyrene as a proto-African-disciple.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
