        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And it was the third hour, and they crucified him&#x27; — Cyril marks the Markan-distinctive precise-time-stamp (third hour = 9 AM Jewish-reckoning). Mark&#x27;s-temporal-precision through Mk 15: third-hour (15:25 crucifixion) → sixth-hour darkness-begins (15:33) → ninth-hour Christ&#x27;s-cry (15:34) → ninth-hour death (15:37). Six hours on the Cross. The third-and-sixth-and-ninth liturgical-hours (still preserved in Tewahedo Daily-Office) commemorate Christ&#x27;s-Passion at these precise-moments.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
