        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;When the sixth hour was come, there was darkness over the whole land until the ninth hour&#x27; — Cyril marks the three-hour darkness as the supernatural-eclipse (NOT astronomical-eclipse — Passover is full-moon, no eclipse-possible). Amos 8:9 LXX echoes: &#x27;I will cause the sun to set at noon, and darken the earth in the clear day.&#x27; The cosmos-mourns the Creator&#x27;s-death. Tewahedo Holy-Friday liturgy + the Mäshafä-Mistir cosmological theology cite Mk 15:33 + Amos 8:9 as the cosmos-mourning prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
