        "Topic.",
        "<strong>Topics.</strong> This verse appears under: DKLIVEIIANCE FROM, AFFLICTIONS, ELOI, THE KING OF THE JEWS, LAMA SABACHTHANI. <em>[Reviewer: pick one topic (typically the first or most theologically loaded), write a 2–3 sentence thematic note, and discard the rest.]</em>",
