        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Jesus cried with a loud voice, and gave up the ghost&#x27; — Cyril marks the Markan-distinctive aphēken-to-pneuma (sent-forth-the-spirit; Matthew has the parallel aphēken-to-pneuma at Mt 27:50; John&#x27;s Jn 19:30 has paredōken-to-pneuma) as the voluntary-self-relinquishing of Christ&#x27;s-spirit. He doesn&#x27;t die-passively; he gives-up-his-spirit actively. The phōnēn-megalēn (loud cry) signals Christic-strength-at-death (not exhaustion). Tewahedo Christological-voluntary-death tradition (against any docetic-or-Apollinarian under-emphasis on Christ&#x27;s-active-self-offering) anchors here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
