        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And the veil of the temple was rent in twain from the top to the bottom&#x27; — Cyril marks the Markan-distinctive schizō (rent) — THE SAME VERB used of the heavens-rent at Mk 1:10 (γ.4.7.B anchor). Mark&#x27;s-bookend-structure: heaven-rent at baptism → temple-veil-rent at crucifixion. The &#x27;from the top to the bottom&#x27; (ap-anōthen-eōs-katō) signals divine-agency (no human could rip top-down). The maqdas-curtain-barrier-now-passable (Heb 10:19-20) is the new-covenant signal. Tewahedo Holy-Friday + Tabot-veil theology reads Mk 15:38 + Mk 1:10 + Heb 10:19-20 as the schizō-bookended new-covenant-access anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
