        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Who shall roll us away the stone from the door of the sepulchre?&#x27; — Cyril marks the Markan-distinctive women&#x27;s-interior-dialogue. The practical-question (who-will-roll-the-stone) reveals their bringing-spices-without-realistic-execution-plan. Mark 16:4 immediately resolves: &#x27;the stone was rolled away: for it was very great&#x27;. The divine-providence outpaces human-planning. Tewahedo trust-in-providence spirituality cites Mk 16:3-4 as the human-anxiety-divine-anticipation pattern.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
