        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Entering into the sepulchre, they saw a young man sitting on the right side, clothed in a long white garment; and they were affrighted&#x27; — Cyril marks the Markan-distinctive neaniskon (young-man) — same word used at Mk 14:51 (the young-man-fled-naked, John-Mark-tradition). Some commentators see deliberate-parallel: the young-man-naked-at-the-arrest is restored as the young-man-clothed-in-white at the Resurrection. The stolēn-leukēn (white-robe) signals the Resurrection-angelic-messenger. Tewahedo Resurrection-iconography + baptismal-white-robe theology cite Mk 16:5 + the Resurrection-narrative as the white-robe Resurrection-significance anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
