        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he saith unto them, Be not affrighted: Ye seek Jesus of Nazareth, which was crucified: he is risen; he is not here: behold the place where they laid him&#x27; — Cyril marks the Markan-angelic-proclamation (ēgerthē, ouk estin hōde — he-is-risen, he-is-not-here) as the foundational Easter-kerygma. The passive ēgerthē (he-was-raised) emphasizes Father-as-agent of Resurrection (cf. Acts 2:24); the perfect-state ouk-estin-hōde (is-not-here) emphasizes the empty-tomb. The mē ekthambeisthe (be-not-amazed) is the angelic-encouragement-formula. Tewahedo Fasika dawn-Eucharist liturgy cites Mk 16:6 + Mt 28:6 + Lk 24:6 + Jn 20:7 as the four-fold resurrection-proclamation-witness, with Mk 16:6 read first per the Markan-priority hypothesis preserved in the Coptic-Tewahedo lectionary tradition.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
