        7,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;But go your way, tell his disciples AND PETER that he goeth before you into Galilee: there shall ye see him, as he said unto you&#x27; — Cyril marks the Markan-distinctive &#x27;AND PETER&#x27; (kai tō Petrō) as the explicit-Petrine-restoration mention. After Peter&#x27;s three-fold-denial (Mk 14:66-72), the Resurrection-angel singles-out-Peter for special-restoration. The Markan-tradition (Mark = Peter&#x27;s-translator per early-Church witness) preserves the personal-restoration-touch Peter himself would have remembered. Tewahedo Petrine-restoration tradition + Coptic-Markan-veneration cite Mk 16:7 + Jn 21:15-17 as the Petrine-restoration dual-anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
