        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Go ye into all the world, and preach the gospel to every creature&#x27; — Cyril marks the Markan-Great-Commission (Mk 16:15-16 in the longer-ending preserved by the Coptic-Tewahedo textform; Tewahedo lectionary reads this on Fasika + Pentecost). The poreuthentes-eis-ton-kosmon-hapanta (going-into-all-the-world) + kēryxate-to-euangelion-pasē-tē-ktisei (preach-the-gospel-to-every-creature) is the universal-mission-mandate. Tewahedo missionary-theology (Frumentius&#x27;s mission to Aksum + the Nine-Saints + contemporary-vernacular-Bible-translation programs) draws Christic-warrant from Mk 16:15 + Mt 28:19-20 + Acts 1:8 as the triple-mission-mandate. With this Markan-anchor, the FOURTH-and-final canonical-Gospel Cyrillian arc closes on the universal-mission-commission — fitting for the Gospel that the Tewahedo-Church traces its own apostolic-succession through (Mark → Anianus → ... → Athanasius → Frumentius).</p></aside>',
